CREATE VIEW mart_recommendation_combined_v2 AS SELECT t.GameKey, t.GameID, t.GameTitle, t.PlayStatusName, t.taste_affinity_score, t.taste_affinity_status, ca.conditional_affinity_percentile, p.ControlSchemeRisk, p.RhythmFlag, p.SHMUPFlag, p.SoulslikeFlag, p.MitigationAvailable, p.playability_adjustment, p.playability_status, p.hard_exclusion_flag, p.exclusion_reason, CASE  WHEN (((p.SoulslikeFlag = CAST('t' AS BOOLEAN)) OR (p.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (p.ControlSchemeRisk IN ('Moderate', 'High')))) THEN (CAST('t' AS BOOLEAN)) ELSE CAST('f' AS BOOLEAN) END AS conditional_path_relevant, CASE  WHEN ((p.hard_exclusion_flag = CAST('t' AS BOOLEAN))) THEN (NULL) WHEN ((((p.SoulslikeFlag = CAST('t' AS BOOLEAN)) OR (p.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (p.ControlSchemeRisk IN ('Moderate', 'High'))) AND (p.MitigationAvailable = CAST('t' AS BOOLEAN)) AND (ca.conditional_affinity_percentile IS NOT NULL))) THEN (ca.conditional_affinity_percentile) ELSE t.taste_affinity_score END AS selected_affinity_score, CASE  WHEN ((p.hard_exclusion_flag = CAST('t' AS BOOLEAN))) THEN ('Excluded') WHEN ((((p.SoulslikeFlag = CAST('t' AS BOOLEAN)) OR (p.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (p.ControlSchemeRisk IN ('Moderate', 'High'))) AND (p.MitigationAvailable = CAST('t' AS BOOLEAN)) AND (ca.conditional_affinity_percentile IS NOT NULL))) THEN ('Conditional Affinity') WHEN ((t.taste_affinity_score IS NULL)) THEN ('Insufficient Metadata') ELSE 'Normal Affinity' END AS affinity_path, CASE  WHEN ((p.hard_exclusion_flag = CAST('t' AS BOOLEAN))) THEN (NULL) WHEN ((((p.SoulslikeFlag = CAST('t' AS BOOLEAN)) OR (p.SHMUPFlag = CAST('t' AS BOOLEAN)) OR (p.ControlSchemeRisk IN ('Moderate', 'High'))) AND (p.MitigationAvailable = CAST('t' AS BOOLEAN)) AND (ca.conditional_affinity_percentile IS NOT NULL))) THEN (round((ca.conditional_affinity_percentile + p.playability_adjustment), 2)) WHEN ((t.taste_affinity_score IS NULL)) THEN (NULL) ELSE round((t.taste_affinity_score + p.playability_adjustment), 2) END AS provisional_recommendation_score FROM mart_taste_affinity_v1 AS t LEFT JOIN mart_playability_v1 AS p ON ((p.GameKey = t.GameKey)) LEFT JOIN vw_conditional_affinity_normalized AS ca ON ((ca.GameKey = t.GameKey));
